'use client'
/** Text Field: the MATRIX card `ui-text-field` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-text-field')!

export type MatrixTextFieldProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixTextField(props: MatrixTextFieldProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
